      aria-hidden="true"
      {...props}
    >
      <circle cx="8.5" cy="14.5" r="4.5" /><path d="M12 11 L20 3.5 M16.5 7 L18.8 4.7 M14.5 9 L16.8 6.7" /><circle cx="8.5" cy="14.5" r="1.2" />
